if (!file_exists($filename)) {
    die("File not found: $filename");
}

$handle = fopen($filename, 'r');
if (!$handle) {
    die("Cannot open file: $filename");
}

$lineNumber = 1;
while (($line = fgets($handle)) !== false) {
    echo "Line $lineNumber: " . htmlspecialchars($line) . "<br>\n";
    $lineNumber++;
}

fclose($handle);
?>
```

**Input** (`quotes.txt`):
```
